<?php if(\App\Executives\AppointmentService::ready()): $serviceHistory=\App\Executives\LifecycleService::history((int)$voter['id'],$_GET); ?>
<section class="card member-panel mb-4" id="member-executive-history"><div class="card-header"><h2 class="card-title">Executive service timeline</h2><span class="small text-secondary"><?= number($serviceHistory['total']) ?> closed records</span></div><div class="card-body">
<p class="small text-secondary">Completed terms and cancelled reservations remain linked to this person, including earlier memberships. Cancelled reservations are labelled separately from actual service.</p>
<?php if(!$serviceHistory['rows']): ?><p class="text-secondary mb-0">No completed terms or cancelled reservations recorded.</p><?php else: ?><ol class="member-activity-list"><?php foreach($serviceHistory['rows'] as $term): ?><li><span class="member-activity-dot" aria-hidden="true"></span><div><strong><a href="<?= e(url('executive_appointment',['id'=>$term['id']])) ?>"><?= e($term['position_name_snapshot']) ?></a></strong><p><?= e(\App\Executives\OrganizationService::label($term)) ?> &middot; <?= e(\App\Executives\PositionService::LEVELS[$term['organization_level']]) ?> · <?= e($term['jurisdiction_snapshot']) ?></p><?php if($term['cancelled_at']): ?><span class="badge bg-secondary">Cancelled · not served</span><p>Cancelled <?= e(date_display($term['cancelled_at'])) ?>; planned start <?= e(date_display($term['starts_on'])) ?></p><?php else: ?><p><?= e(date_display($term['starts_on'])) ?> — <?= e(date_display($term['ended_on'])) ?></p><span class="badge bg-secondary"><?= e(\App\Executives\LifecycleService::REASONS[$term['end_reason']]??$term['end_reason']) ?></span><?php endif; ?></div></li><?php endforeach; ?></ol>
<?php if($serviceHistory['last']>1): ?><nav class="d-flex align-items-center gap-3 mt-3" aria-label="Executive history pages"><span class="small text-secondary">Page <?= number($serviceHistory['p']) ?> of <?= number($serviceHistory['last']) ?></span><?php foreach(['Previous'=>$serviceHistory['p']-1,'Next'=>$serviceHistory['p']+1] as $label=>$page): ?><?php if($page>=1&&$page<=$serviceHistory['last']): ?><a class="btn btn-sm btn-light" href="<?= e(url('member',['id'=>$voter['membership_id'],'executive_history_p'=>$page]).'#member-executive-history') ?>"><?= e($label) ?></a><?php endif; ?><?php endforeach; ?></nav><?php endif; endif; ?>
</div></section><?php endif; ?>
